// default: std::less gives a max-heap, top() is the largest
std::priority_queue<int> maxq;

// min-heap: spell out the container AND std::greater
std::priority_queue<int, std::vector<int>,
                    std::greater<int>> minq;

// custom: cmp(a, b) == true means a has LOWER priority
struct Task { int prio; std::string name; };
auto cmp = [](const Task& a, const Task& b) {
    return a.prio < b.prio;          // highest prio on top
};
std::priority_queue<Task, std::vector<Task>,
                    decltype(cmp)> tasks(cmp);

std::vector<int> data = {4, 9, 2, 7};
std::priority_queue<int> pq(data.begin(), data.end());  // O(n)

